import{_ as l,o as e,c as t,a2 as r}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"把法律经验做成可复用的 AI Skills","description":"","frontmatter":{"title":"把法律经验做成可复用的 AI Skills","date":"2026-09-01T00:00:00.000Z","category":"AI 工作流成果","summary":"把交易文件审阅、投后回购管理、Cap Table 计算和投融资法律尽调经验，整理成四项有边界、有步骤、可复核的 AI 工作成果。","number":"07","tags":["法律 AI","VC/PE","投后管理","Cap Table","法律尽调","工作流"]},"headers":[],"relativePath":"work/legal-ai-skills-portfolio.md","filePath":"work/legal-ai-skills-portfolio.md","lastUpdated":1788339898000}'),i={name:"work/legal-ai-skills-portfolio.md"};function o(s,a,p,n,h,d){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="把法律经验做成可复用的-ai-skills" tabindex="-1">把法律经验做成可复用的 AI Skills <a class="header-anchor" href="#把法律经验做成可复用的-ai-skills" aria-label="Permalink to &quot;把法律经验做成可复用的 AI Skills&quot;">​</a></h1><p>最近一段时间，我把自己在投融资交易和投后管理中反复遇到的几类工作，陆续整理成了四项可以独立使用、持续迭代的 AI 工作成果。</p><p>我想做的并不是让 AI “写得更快”，而是把那些原本只存在于个人经验里的判断方法，拆成有边界、有步骤、能复核的工作流程。这样换一个项目、换一份文件，仍然可以沿着同一套逻辑继续工作。</p><h2 id="_01-交易文件审阅-先识别角色-再进入条款" tabindex="-1">01｜交易文件审阅：先识别角色，再进入条款 <a class="header-anchor" href="#_01-交易文件审阅-先识别角色-再进入条款" aria-label="Permalink to &quot;01｜交易文件审阅：先识别角色，再进入条款&quot;">​</a></h2><p>第一组是 <strong>VC/PE 投资文件审阅 Skills</strong>，覆盖 Term Sheet、投资协议、股东协议和交割文件。</p><p>它不会拿到文件就直接逐条改字，而是先确认文件类型、审阅方身份、交易轮次和目标，再决定需要调用哪套审阅规则。除了提示条款风险，也会检查交易结构、权利是否完整、文件之间是否一致，以及尽调问题有没有落实到交割条件。</p><p><a href="https://github.com/Hellyai/transaction-legal-skills-" target="_blank" rel="noreferrer">查看交易法律 Skills →</a></p><h2 id="_02-投后回购管理-把分散事项收进一张持续更新的清单" tabindex="-1">02｜投后回购管理：把分散事项收进一张持续更新的清单 <a class="header-anchor" href="#_02-投后回购管理-把分散事项收进一张持续更新的清单" aria-label="Permalink to &quot;02｜投后回购管理：把分散事项收进一张持续更新的清单&quot;">​</a></h2><p>第二项是 <strong>投后回购事项管理小程序</strong>。</p><p>项目数量增加以后，回购触发条件、通知时间、沟通记录和后续进展往往散落在合同、表格和聊天记录里。我把这些信息重新整理成一套可以持续维护的管理页面，供投资机构投后团队、法务和基金运营人员集中查看。</p><p>它解决的不是“生成一份总结”，而是让每个项目当前处于什么状态、下一步由谁跟进、哪些节点不能遗漏，变得更清楚。</p><p><a href="/agents/redemptioncontrol">查看投后回购事项管理小程序 →</a></p><h2 id="_03-cap-table-把复杂计算变成可追溯的过程" tabindex="-1">03｜Cap Table：把复杂计算变成可追溯的过程 <a class="header-anchor" href="#_03-cap-table-把复杂计算变成可追溯的过程" aria-label="Permalink to &quot;03｜Cap Table：把复杂计算变成可追溯的过程&quot;">​</a></h2><p>第三项是 <strong>Cap Table Skill</strong>。</p><p>它用于处理增资、老股转让、混合交易、多轮融资和连续反摊薄计算。相比只给一个最终持股比例，我更在意每一步的口径是否说得清楚：本轮投前股本是多少、价格如何调整、补偿股数从哪里来，以及各张表之间能不能勾稽一致。</p><p>最终交付的不只是数字，也包括可以复核的计算过程。</p><p><a href="https://github.com/Hellyai/cap-table-skill" target="_blank" rel="noreferrer">查看 Cap Table Skill →</a></p><h2 id="_04-法律尽调-按项目阶段决定工作深度" tabindex="-1">04｜法律尽调：按项目阶段决定工作深度 <a class="header-anchor" href="#_04-法律尽调-按项目阶段决定工作深度" aria-label="Permalink to &quot;04｜法律尽调：按项目阶段决定工作深度&quot;">​</a></h2><p>第四项是 <strong>投融资法律尽调 Skill</strong>。</p><p>我把它拆成两个阶段：项目只有 BP 或立项材料时，先识别影响投资判断的明显红旗，形成尽调重点和首轮文件清单；收到成批资料后，再进入完整尽调，处理资料缺失、事实矛盾、补充问题、风险闭环和正式报告。</p><p>这样做，是为了避免材料还很少时就生成一份看似完整、实际上缺少事实依据的报告。</p><p><a href="https://github.com/Hellyai/investment-legal-dd-skill" target="_blank" rel="noreferrer">查看投融资法律尽调 Skill →</a></p><h2 id="四项成果背后-其实是同一种工作方法" tabindex="-1">四项成果背后，其实是同一种工作方法 <a class="header-anchor" href="#四项成果背后-其实是同一种工作方法" aria-label="Permalink to &quot;四项成果背后，其实是同一种工作方法&quot;">​</a></h2><p>虽然它们分别处理文件审阅、投后管理、股权计算和法律尽调，但底层逻辑很接近：</p><ol><li>先确认角色、材料和任务边界；</li><li>把复杂工作拆成能够执行的步骤；</li><li>保留来源、计算口径和待核实事项；</li><li>让结果能够被专业人员继续检查和接管。</li></ol><p>这些 Skill 还会继续更新。对我来说，真正值得沉淀的不是某一次 AI 输出，而是完成项目之后，能不能把其中的方法留下来，下一次继续使用。</p>',26)])])}const _=l(i,[["render",o]]);export{k as __pageData,_ as default};
